// The GetHashCode/Equals contract -- getting this wrong breaks Dictionary silently
public class OrderKey
{
    public int CustomerId { get; set; }
    public string Region { get; set; }

    public override bool Equals(object obj) =>
        obj is OrderKey other && CustomerId == other.CustomerId && Region == other.Region;

    // MUST be overridden alongside Equals -- HashCode.Combine is the modern standard
    public override int GetHashCode() => HashCode.Combine(CustomerId, Region);
}

